        vec![Constraint::Percentage(100), Constraint::Percentage(50), Constraint::Percentage(100)],
        vec![Constraint::Ratio(1,2), Constraint::Ratio(1,2)],
        vec![Constraint::Percentage(0), Constraint::Percentage(100), Constraint::Percentage(100)],
        vec![Constraint::Length(0), Constraint::Fill(1), Constraint::Length(8)],
