//! Small helper crate that shells out to the platform `ping` binary and parses
//! its output.  This is what `gping` uses to gather the graph data.
use std::io::{BufRead, BufReader};
use std::net::IpAddr;
use std::process::{Child, Command, Stdio};
use std::sync::mpsc::Sender;
use std::thread;
use std::time::Duration;

/// A single ping response (or a timeout).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct PingResult {
    pub seq: usize,
    pub time: Duration,
    pub timeout: bool,
}

/// The command used to figure out which ping implementation we are dealing with.
pub fn get_ping_version_cmd(addr: IpAddr) -> Command {
    if addr.is_ipv6() {
        let mut c = Command::new("ping6");
        c.arg("-V");
        c
    } else {
        let mut c = Command::new("ping");
        c.arg("-V");
        c
    }
}

/// Build the command that streams ping results for `addr`.
pub fn get_ping_cmd(
    addr: IpAddr,
    interval: f64,
    iface: Option<&str>,
    extra_args: &[String],
) -> Command {
    let mut cmd = if addr.is_ipv6() {
        Command::new("ping6")
    } else {
        Command::new("ping")
    };
    cmd.arg("-O");
    cmd.arg(format!("-i{:.1}", interval));
    if let Some(i) = iface {
        cmd.arg(format!("-I{}", i));
    }
    cmd.args(extra_args);
    cmd.arg(addr.to_string());
    cmd
}

/// Verify that the `ping` binary we are about to use is one we understand.
pub fn get_ping_version(addr: IpAddr) -> Result<(), String> {
    let out = get_ping_version_cmd(addr)
        .output()
        .map_err(|e| format!("Error spawning ping: {e}"))?;
    let stdout: Vec<String> = String::from_utf_lossy(&out.stdout)
        .lines()
        .map(|s| s.to_string())
        .collect();
    let stderr: Vec<String> = String::from_utf_lossy(&out.stderr)
        .lines()
        .map(|s| s.to_string())
        .collect();
    if stdout.iter().chain(stderr.iter()).any(|l| l.contains("iputils")) {
        Ok(())
    } else {
        Err(format!(
            "Could not detect ping. Stderr: {:?}\nStdout: {:?}",
            stderr, stdout
        ))
    }
}

/// Spawn `ping` and forward every parsed response to `tx`.
pub fn ping_host(
    addr: IpAddr,
    interval: f64,
    iface: Option<&str>,
    extra_args: &[String],
    tx: Sender<PingResult>,
) -> Result<Child, String> {
    get_ping_version(addr)?;
    let mut cmd = get_ping_cmd(addr, interval, iface, extra_args);
    cmd.stdout(Stdio::piped()).stderr(Stdio::null());
    let mut child = cmd
        .spawn()
        .map_err(|e| format!("Error spawning ping: {e}"))?;
    let stdout = child.stdout.take().unwrap();
    let _ = thread::spawn(move || {
        let reader = BufReader::new(stdout);
        for line in reader.lines() {
            let Ok(line) = line else { break };
            if let Some(res) = parse_ping_line(&line) {
                if tx.send(res).is_err() {
                    break;
                }
            }
        }
    });
    Ok(child)
}

/// Parse a single line of iputils `ping -O` output.
pub fn parse_ping_line(line: &str) -> Option<PingResult> {
    if let Some(rest) = line.strip_prefix("no answer yet for icmp_seq=") {
        let seq: usize = rest.trim_end_matches(|c: char| !c.is_ascii_digit()).parse().ok()?;
        return Some(PingResult {
            seq,
            time: Duration::ZERO,
            timeout: true,
        });
    }
    // "64 bytes from 1.2.3.4: icmp_seq=1 ttl=64 time=0.100 ms"
    let seq = line.split("icmp_seq=").nth(1)?;
    let seq: usize = seq
        .chars()
        .take_while(|c| c.is_ascii_digit())
        .collect::<String>()
        .parse()
        .ok()?;
    let idx = line.find("time=")?;
    let rest = &line[idx + 5..];
    let num: String = rest
        .chars()
        .take_while(|c| c.is_ascii_digit() || *c == '.')
        .collect();
    let ms: f64 = num.parse().ok()?;
    Some(PingResult {
        seq,
        time: Duration::from_secs_f64(ms / 1000.0),
        timeout: false,
    })
}
RSEOF
