mod braille;
mod colors;
mod render;
mod stats;

use std::net::IpAddr;
use std::sync::mpsc::{channel, Receiver};
use std::time::{Duration, Instant};

use anyhow::Context;
use clap::builder::{Arg, Command, ArgPredicate};
use crossterm::event::{Event, KeyCode, KeyEvent, KeyModifiers};
use pinger::{PingResult, PingOutcome};

use crate::colors::Colors;
use crate::render::GraphData;

/// CLI options
#[derive(Debug, Clone)]
pub struct Args {
    pub hosts: Vec<String>,
    pub cmd: bool,
    pub watch_interval: Option<f64>,
    pub buffer: f64,
    pub ipv4: bool,
    pub ipv6: bool,
    pub interface: Option<String>,
    pub simple_graphics: bool,
    pub vertical_margin: u16,
    pub horizontal_margin: u16,
    pub colors: Vec<String>,
    pub clear: bool,
    pub ping_args: Vec<String>,
}

fn build_cli() -> Command {
    let color_help = "Assign color to a graph entry.\n\nThis option can be defined more than once as a comma separated string, and the order which the colors are provided will be matched against the hosts or commands passed to gping.\n\nHexadecimal RGB color codes are accepted in the form of '#RRGGBB' or the following color names: 'black', 'red', 'green', 'yellow', 'blue', 'magenta','cyan', 'gray', 'dark-gray', 'light-red', 'light-green', 'light-yellow', 'light-blue', 'light-magenta', 'light-cyan', and 'white'";
    Command::new("gping")
        .version(format!("gping {}", env!("CARGO_PKG_VERSION")))
        .long_version(format!(
            "gping {}\ncommit_hash: {}\nbuild_time: {}\nbuild_env: {}",
            env!("CARGO_PKG_VERSION"),
            option_env!("GPING_COMMIT_HASH").unwrap_or("unknown"),
            option_env!("GPING_BUILD_TIME").unwrap_or("unknown"),
            option_env!("GPING_BUILD_ENV").unwrap_or("unknown"),
        ))
        .arg(
            Arg::new("hosts_or_commands")
                .num_args(0..)
                .value_name("HOSTS_OR_COMMANDS")
                .long_help("Hosts or IPs to ping, or commands to run if --cmd is provided. Can use cloud shorthands like aws:eu-west-1"),
        )
        .arg(
            Arg::new("cmd")
                .long("cmd")
                .long_help("Graph the execution time for a list of commands rather than pinging hosts"),
        )
        .arg(
            Arg::new("watch_interval")
                .short('n')
                .long("watch-interval")
                .value_name("WATCH_INTERVAL")
                .long_help("Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5"),
        )
        .arg(
            Arg::new("buffer")
                .short('b')
                .long("buffer")
                .value_name("BUFFER")
                .default_value("30")
                .long_help("Determines the number of seconds to display in the graph"),
        )
        .arg(Arg::new("ipv4").short('4').long_help("Resolve ping targets to IPv4 address"))
        .arg(Arg::new("ipv6").short('6').long_help("Resolve ping targets to IPv6 address"))
        .arg(
            Arg::new("interface")
                .short('i')
                .long("interface")
                .value_name("INTERFACE")
                .long_help("Interface to use when pinging"),
        )
        .arg(Arg::new("simple_graphics").short('s').long("simple-graphics").long_help(""))
        .arg(
            Arg::new("vertical_margin")
                .long("vertical-margin")
                .value_name("VERTICAL_MARGIN")
                .default_value("1")
                .long_help("Vertical margin around the graph (top and bottom)"),
        )
        .arg(
            Arg::new("horizontal_margin")
                .long("horizontal-margin")
                .value_name("HORIZONTAL_MARGIN")
                .default_value("0")
                .long_help("Horizontal margin around the graph (left and right)"),
        )
        .arg(
            Arg::new("color")
                .short('c')
                .long("color")
                .value_name("color")
                .action(ArgPredicate::Append)
                .long_help(color_help),
        )
        .arg(
            Arg::new("clear")
                .long("clear")
                .long_help("Clear the graph from the terminal after closing the program"),
        )
        .arg(
            Arg::new("ping_args")
                .long("ping-args")
                .num_args(0..)
                .value_name("PING_ARGS")
                .long_help("Extra arguments to pass to `ping`. These are platform dependent"),
        )
        .after_help("")
}

fn parse_args() -> anyhow::Result<Args> {
    let m = build_cli().get_matches();
    let hosts: Vec<String> = m.get_many::<String>("hosts_or_commands")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let buffer: f64 = m.get_one::<String>("buffer").unwrap().parse()?;
    let watch_interval = match m.get_one::<String>("watch_interval") {
        Some(v) => Some(v.parse::<f64>()?),
        None => None,
    };
    let vertical_margin: u16 = m.get_one::<String>("vertical_margin").unwrap().parse()?;
    let horizontal_margin: u16 = m.get_one::<String>("horizontal_margin").unwrap().parse()?;
    let colors: Vec<String> = m.get_many::<String>("color")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let ping_args: Vec<String> = m.get_many::<String>("ping_args")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    Ok(Args {
        hosts,
