        .arg(Arg::new("simple_graphics").short('s').long("simple-graphics").long_help(""))
        .arg(
            Arg::new("vertical_margin")
                .long("vertical-margin")
                .value_name("VERTICAL_MARGIN")
                .default_value("1")
                .long_help("Vertical margin around the graph (top and bottom)"),
        )
        .arg(
            Arg::new("horizontal_margin")
                .long("horizontal-margin")
                .value_name("HORIZONTAL_MARGIN")
                .default_value("0")
                .long_help("Horizontal margin around the graph (left and right)"),
        )
        .arg(
            Arg::new("color")
                .short('c')
                .long("color")
                .value_name("color")
                .action(ArgPredicate::Append)
                .long_help(color_help),
        )
        .arg(
            Arg::new("clear")
                .long("clear")
                .long_help("Clear the graph from the terminal after closing the program"),
        )
        .arg(
            Arg::new("ping_args")
                .long("ping-args")
                .num_args(0..)
                .value_name("PING_ARGS")
                .long_help("Extra arguments to pass to `ping`. These are platform dependent"),
        )
        .after_help("")
}

fn parse_args() -> anyhow::Result<Args> {
    let m = build_cli().get_matches();
    let hosts: Vec<String> = m.get_many::<String>("hosts_or_commands")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let buffer: f64 = m.get_one::<String>("buffer").unwrap().parse()?;
    let watch_interval = match m.get_one::<String>("watch_interval") {
        Some(v) => Some(v.parse::<f64>()?),
        None => None,
    };
    let vertical_margin: u16 = m.get_one::<String>("vertical_margin").unwrap().parse()?;
    let horizontal_margin: u16 = m.get_one::<String>("horizontal_margin").unwrap().parse()?;
    let colors: Vec<String> = m.get_many::<String>("color")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let ping_args: Vec<String> = m.get_many::<String>("ping_args")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    Ok(Args {
        hosts,
        cmd: m.get_flag("cmd"),
        watch_interval,
        buffer,
        ipv4: m.get_flag("ipv4"),
        ipv6: m.get_flag("ipv6"),
        interface: m.get_one::<String>("interface").cloned(),
        simple_graphics: m.get_flag("simple_graphics"),
        vertical_margin,
        horizontal_margin,
        colors,
        clear: m.get_flag("clear"),
        ping_args,
    })
}

/// Turn a host (or command) into the thing we actually resolve.
fn expand_host(host: &str) -> String {
    if let Some((prefix, rest)) = host.split_once(':') {
        if prefix == "aws" {
            return format!("ec2.{rest}.amazonaws.com");
        }
    }
    host.to_string()
}

/// Resolve a host string into an IP address.
fn resolve(host: &str, ipv4: bool, ipv6: bool) -> anyhow::Result<IpAddr> {
    use std::net::ToSocketAddrs;
    let target = expand_host(host);
    let addrs: Vec<IpAddr> = target
        .to_socket_addrs()
        .with_context(|| format!("Resolving {host}"))?
        .map(|a| a.ip())
        .collect();
    let picked = if ipv4 {
        addrs.iter().find(|a| a.is_ipv4()).copied()
    } else if ipv6 {
        addrs.iter().find(|a| a.is_ipv6()).copied()
    } else {
        addrs.first().copied()
    };
    picked.ok_or_else(|| anyhow::anyhow!("Resolving {host}"))
}

fn main() {
    let args = match parse_args() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{e:?}");
            std::process::exit(2);
        }
    };
    if args.hosts.is_empty() {
        eprintln!("Error: At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.");
        std::process::exit(1);
    }
    if let Err(e) = run(&args) {
        eprintln!("Error: {e:?}");
        std::process::exit(1);
    }
}

struct Entry {
    label: String,
    addr: Option<IpAddr>,
    command: Option<String>,
    color: ratatui::style::Color,
    rx: Receiver<PingOutcome>,
    samples: std::collections::VecDeque<Sample>,
    child: Option<std::process::Child>,
}

#[derive(Debug, Clone, Copy)]
struct Sample {
    t: Instant,
    v: f64,
    timeout: bool,
}

fn run(args: &Args) -> anyhow::Result<()> {
    let watch_interval = args
        .watch_interval
        .unwrap_or(if args.cmd { 0.5 } else { 0.2 });
    let buffer = Duration::from_secs_f64(args.buffer);
    let colors = Colors::parse(&args.colors, args.hosts.len())?;

    let mut entries: Vec<Entry> = Vec::new();
    for (host, color) in args.hosts.iter().zip(colors.iter()) {
        let (addr, command) = if args.cmd {
            (None, Some(host.clone()))
        } else {
            (Some(resolve(host, args.ipv4, args.ipv6)?), None)
        };
        let (tx, rx) = channel();
        let child = if let Some(addr) = addr {
            Some(pinger::ping_host(
                addr,
                watch_interval,
                args.interface.as_deref(),
                &args.ping_args,
                tx,
            )?)
        } else {
            spawn_cmd(host.clone(), tx)
        };
        entries.push(Entry {
            label: host.clone(),
            addr,
            command,
            color,
            rx,
            samples: Default::default(),
            child,
        });
    }

    let mut terminal = render::init()?;
    let res = event_loop(&mut terminal, &mut entries, args, watch_interval, buffer);
    render::restore(&mut terminal, args.clear)?;
    if let Some(child) = entries.iter().flat_map(|e| e.child.as_ref()).next() {
        let _ = child;
    }
    for e in entries.iter_mut() {
        if let Some(c) = e.child.as_mut() {
            let _ = c.kill();
        }
    }
    res
}

fn spawn_cmd(cmd: String, tx: std::sync::mpsc::Sender<PingOutcome>) -> Option<std::process::Child> {
    use std::process::{Command, Stdio};
    let Ok(mut child) = Command::new("sh")
        .arg("-c")
        .arg(&cmd)
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
    else {
        return None;
    };
    let stdout = child.stdout.take().unwrap();
    let _ = std::thread::spawn(move || {
        use std::io::BufRead;
        let reader = std::io::BufReader::new(stdout);
        for line in reader.lines() {
            let Ok(line) = line else { break };
            let start = std::time::Instant::now();
            let _ = start;
            if tx.send(PingOutcome::Command(line, std::time::Instant::now())).is_err() {
                break;
            }
        }
    });
    Some(child)
}

fn event_loop(
    terminal: &mut ratatui::Terminal<ratatui::backend::CrosstermBackend<std::io::Stdout>>,
    entries: &mut [Entry],
    args: &Args,
    watch_interval: f64,
    buffer: Duration,
) -> anyhow::Result<()> {
    let interval = Duration::from_secs_f64(watch_interval);
    let mut last_draw = Instant::now();
    loop {
        // gather results
        for e in entries.iter_mut() {
            while let Ok(res) = e.rx.try_recv() {
                match res {
                    PingOutcome::Pong(PingResult { time, timeout, .. }) => {
                        e.samples.push_back(Sample {
                            t: Instant::now(),
                            v: time.as_secs_f64(),
                            timeout,
                        });
                    }
                    PingOutcome::Command(_, t) => {
                        // handled below
                        let _ = t;
                    }
                }
            }
        }
        // command mode: measure elapsed time of each command run
        if args.cmd {
            for e in entries.iter_mut() {
                while let Ok(res) = e.rx.try_recv() {
                    if let PingOutcome::Command(_, _) = res {}
                }
            }
        }
        let now = Instant::now();
        let _ = now;
        if last_draw.elapsed() >= interval {
            last_draw = Instant::now();
            let data = build_data(entries, buffer);
            terminal.draw(|f| render::draw(f, &data, args))?;
        }
        if crossterm::event::poll(Duration::from_millis(10))? {
            if let Event::Key(KeyEvent { code, modifiers, .. }) = crossterm::event::read()? {
                match code {
                    KeyCode::Char('q') | KeyCode::Esc => break,
                    KeyCode::Char('c') if modifiers.contains(KeyModifiers::CONTROL) => break,
                    KeyCode::Char('q') if modifiers.contains(KeyModifiers::CONTROL) => break,
                    _ => {}
                }
            }
        }
    }
    Ok(())
}

fn build_data(entries: &mut [Entry], buffer: Duration) -> Vec<GraphData> {
    let now = Instant::now();
    let mut out = Vec::new();
    for e in entries.iter_mut() {
        while let Ok(res) = e.rx.try_recv() {
            match res {
                PingOutcome::Pong(PingResult { time, timeout, .. }) => {
                    e.samples.push_back(Sample {
                        t: now,
                        v: time.as_secs_f64(),
                        timeout,
                    });
                }
                PingOutcome::Command(start) => {
                    e.samples.push_back(Sample {
                        t: start,
                        v: start.elapsed().as_secs_f64(),
                        timeout: false,
                    });
                }
            }
        }
        let cutoff = now.checked_sub(buffer).unwrap_or(now);
        while let Some(s) = e.samples.front() {
            if s.t < cutoff {
                e.samples.pop_front();
            } else {
                break;
            }
        }
        out.push(GraphData {
            label: e.label.clone(),
            color: e.color,
            samples: e.samples.iter().map(|s| (s.t, s.v, s.timeout)).collect(),
        });
    }
    out
}
RSEOF
echo ok"}

