//! Colour handling: named colours, `#RRGGBB` and the default palette.
use ratatui::style::Color;

pub struct Colors;

const NAMES: &[(&str, u8)] = &[
    ("black", 0),
    ("red", 1),
    ("green", 2),
    ("yellow", 3),
    ("blue", 4),
    ("magenta", 5),
    ("cyan", 6),
    ("gray", 7),
    ("dark-gray", 8),
    ("light-red", 9),
    ("light-green", 10),
    ("light-yellow", 11),
    ("light-blue", 12),
    ("light-magenta", 13),
    ("light-cyan", 14),
    ("white", 15),
];

fn parse_one(s: &str) -> Result<Color, anyhow::Error> {
    let s = s.trim();
    if let Some(hex) = s.strip_prefix('#') {
        if hex.len() == 6 {
            let r = u8::from_str_radix(&hex[0..2], 16).ok();
            let g = u8::from_str_radix(&hex[2..4], 16).ok();
            let b = u8::from_str_radix(&hex[4..6], 16).ok();
            if let (Some(r), Some(g), Some(b)) = (r, g, b) {
                return Ok(Color::Rgb(r, g, b));
            }
        }
        return Err(anyhow::anyhow!("Failed to parse Colors"));
    }
    for (name, idx) in NAMES {
        if *name == s.to_ascii_lowercase().as_str() {
            return Ok(Color::Indexed(*idx));
        }
    }
    Err(anyhow::anyhow!("Failed to parse Colors"))
}

impl Colors {
    /// Parse the `-c` arguments.  Each argument may contain a comma separated
    /// list of colours which are matched against the hosts in order.
    pub fn parse(args: &[String], n_hosts: usize) -> anyhow::Result<Vec<ratatui::style::Color>> {
        let mut out = Vec::new();
        for arg in args {
            for part in arg.split(',') {
                out.push(parse_one(part)?);
            }
        }
        while out.len() < n_hosts {
            out.push(Color::Indexed((out.len() + 2) as u8));
        }
        Ok(out)
    }
}
