//! Formatting of durations and the statistics shown in the header.

/// Format a duration given in microseconds the way gping does.
pub fn format_us(us: f64) -> String {
    if us < 1.0 {
        format!("{}ns", (us * 1000.0) as u64)
    } else if us < 1000.0 {
        format!("{}µs", us as u64)
    } else if us < 1_000_000.0 {
        trim(format!("{:.3}", us / 1000.0)) + "ms"
    } else {
        trim(format!("{:.6}", us / 1_000_000.0)) + "s"
    }
}

fn trim(s: String) -> String {
    let s = s.trim_end_matches('0');
    let s = s.trim_end_matches('.');
    s.to_string()
}

pub struct Stats {
    pub last: f64,
    pub min: f64,
    pub max: f64,
    pub avg: f64,
    pub jtr: f64,
    pub p95: f64,
    pub timeouts: usize,
}

impl Stats {
    pub fn compute(values: &[(f64, bool)]) -> Stats {
        let mut vals: Vec<f64> = values.iter().filter(|(_, t)| !t).map(|(v, _)| *v).collect();
        let timeouts = values.iter().filter(|(_, t)| *t).count();
        if vals.is_empty() {
            return Stats {
                last: 0.0,
                min: 0.0,
                max: 0.0,
                avg: 0.0,
                jtr: 0.0,
                p95: 0.0,
                timeouts,
            };
        }
        vals.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let min = *vals.first().unwrap();
        let max = *vals.last().unwrap();
        let n = vals.len();
        let avg = vals.iter().sum::<f64>() / n as f64;
        let jtr = if n > 1 { (max - min) / (n - 1) as f64 } else { 0.0 };
        let p95 = vals[((n as f64 - 1.0) * 0.95) as usize];
        let last = *values.last().map(|(v, t)| if *t { &0.0 } else { v }).unwrap_or(&0.0);
        Stats {
            last,
            min,
            max,
            avg,
            jtr,
            p95,
            timeouts,
        }
    }
}
RSEOF
echo ok"}

