//! A tiny braille / dot grid used to draw the graph lines.
pub struct Grid {
    /// number of character columns
    pub w: usize,
    /// number of character rows
    pub h: usize,
    /// dots per character column (2 for braille, 1 for simple graphics)
    pub dw: usize,
    /// dots per character row (4 for braille, 1 for simple graphics)
    pub dh: usize,
    cells: Vec<u16>,
}

const BITS: [[u32; 4]; 2] = [
    [0x01, 0x02, 0x04, 0x40], // left column: dots 1,2,3,7
    [0x08, 0x10, 0x20, 0x80], // right column: dots 4,5,6,8
];

impl Grid {
    pub fn new(w: usize, h: usize, braille: bool) -> Self {
        let (dw, dh) = if braille { (2, 4) } else { (1, 1) };
        Grid {
            w,
            h,
            dw,
            dh,
            cells: vec![0u16; w * h],
        }
    }

    pub fn resolution(&self) -> (f64, f64) {
