            return;
        }
        let (dx, dy) = (dx as usize, dy as usize);
        if dx >= self.w * self.dw || dy >= self.h * self.dh {
            return;
        }
        let cx = dx % 2;
        let cy = dy % self.dh;
        let cy = if self.dh == 1 { 0 } else { cy };
        let col = dx / 2;
        let row = dy / self.dh;
        let idx = row * self.w + col;
        if idx < self.cells.len() {
            self.cells[idx] |= BITS[cx][cy] as u16;
        }
    }

    /// Draw a line between two points expressed in grid dot coordinates.
    pub fn line(&mut self, x0: f64, y0: f64, x1: f64, y1: f64) {
        let (rx, ry) = self.resolution();
        let px = |x: f64| -> i64 {
            if !x.is_finite() {
                return i64::MIN;
            }
            ((x * (rx - 1.0)).floor()) as i64
        };
