    let dx = x2.abs_diff(x1);
    let dy = y2.abs_diff(y1);
    if dx == 0 {
        for y in y1.min(y2)..=y1.max(y2) {
            f(x1, y);
        }
    } else if dy == 0 {
        for x in x1.min(x2)..=x1.max(x2) {
            f(x, y1);
        }
    } else if dy < dx {
        if x1 > x2 {
            low(x2, y2, x1, y1, &mut f);
        } else {
            low(x1, y1, x2, y2, &mut f);
        }
    } else if y1 > y2 {
        high(x2, y2, x1, y1, &mut f);
    } else {
