    }
}

fn low<F: FnMut(i64, i64)>(x1: i64, y1: i64, x2: i64, y2: i64, f: &mut F) {
    let dx = (x2 - x1) as i64;
    let dy = (y2 as i64 - y1 as i64).abs();
    let mut d = 2 * dy - dx;
    let mut y = y1;
    for x in x1..=x2 {
