//! Terminal setup/teardown and the actual drawing of the graph.
use std::time::Instant;

use ratatui::backend::CrosstermBackend;
use ratatui::layout::{Constraint, Layout, Rect};
use ratatui::style::{Color, Style, Stylize};
use ratatui::symbols::Marker;
use ratatui::text::{Line, Span};
use ratatui::widgets::canvas::Line as CanvasLine;
use ratatui::widgets::{Canvas, Paragraph};
use ratatui::Terminal;

use crate::braille;
use crate::stats::{format_us, Stats};

pub struct GraphData {
    pub label: String,
    pub color: Color,
    pub samples: Vec<(Instant, f64, bool)>,
}

const GRAY: Color = Color::Indexed(7);

pub fn init() -> anyhow::Result<Terminal<CrosstermBackend<std::io::Stdout>>> {
    crossterm::terminal::enable_raw_mode()?;
    let mut stdout = std::io::stdout();
    crossterm::execute!(stdout, crossterm::terminal::EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    Ok(terminal)
}

pub fn restore(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
    clear: bool,
) -> anyhow::Result<()> {
    if clear {
        crossterm::execute!(terminal.backend_mut(), crossterm::terminal::Clear(crossterm::terminal::ClearType::All))?;
    }
    crossterm::execute!(terminal.backend_mut(), crossterm::terminal::LeaveAlternateScreen)?;
    crossterm::terminal::disable_raw_mode()?;
    Ok(())
}

fn y_bounds(data: &[GraphData]) -> Option<(f64, f64)> {
    let mut mn = f64::MAX;
    let mut mx = f64::MIN;
    for d in data {
        for (_, v, t) in &d.samples {
            if *t {
                continue;
            }
            if *v < mn {
                mn = *v;
            }
            if *v > mx {
                mx = *v;
            }
        }
    }
    if mn > mx {
        return None;
    }
    let lo = mn * 0.9;
    let step = ((mx * 1.1 - lo) / 7.0).floor();
    Some((lo, mx * 1.1, step))
}

pub fn y_ticks(lo: f64, hi: f64) -> Vec<f64> {
    let step = ((hi - lo) / 7.0).floor();
    (0..7).map(|i| lo + i as f64 * step).collect()
}

pub fn draw(
    f: &mut ratatui::Frame,
    data: &[GraphData],
