            d.label.clone(),
            format!("last {}", format_us(st.last)),
            format!("min {}", format_us(st.min)),
            format!("max {}", format_us(st.max)),
            format!("avg {}", format_us(st.avg)),
            format!("jtr {}", format_us(st.jtr)),
            format!("p95 {}", format_us(st.p95)),
            format!("t/o {}", st.timeouts),
        ];
        for (c, text) in chunks.iter().zip(cells.iter()) {
            let para = Paragraph::new(text.as_str()).style(Style::new().fg(d.color));
            f.render_widget(para, *c);
        }
    }

    // y axis labels
    let bounds = y_bounds(data);
    let (lo, hi, _step) = match bounds {
        Some(b) => b,
        None => (0.0, 1.0, 0.0),
    };
    let ticks = y_ticks(lo, hi);
    let lw = ticks
        .iter()
        .map(|t| format_us(*t).chars().count())
