        .unwrap_or(7)
        .max(7) as u16;
    let cols = Layout::horizontal([
        Constraint::Length(lw),
        Constraint::Length(1),
        Constraint::Min(0),
    ])
    .split(graph);
    let label_area = cols[0];
    let axis_col = cols[1];
    let data_area = cols[2];
    let gh = data_area.height as usize;
    for (j, t) in ticks.iter().enumerate() {
        let row = if gh > 1 {
            ((j * (gh - 1) + 5) / 6) as u16
        } else {
            0
        };
        if row < label_area.height {
