            } else {
                (hi - v) / (hi - lo)
            }
        };
        let marker = if args.simple_graphics { Marker::Dot } else { Marker::Braille };
        let canvas = Canvas::default()
            .marker(marker)
            .x_bounds([0.0, span])
            .y_bounds([0.0, 1.0])
            .paint(|ctx| {
                let mut prev: Option<(f64, f64)> = None;
                for (t, v, timeout) in &d.samples {
                    let x = xof(*t);
                    let y = if *timeout { 2.0 } else { yof(*v) };
