fn expand_host(host: &str) -> String {
    if let Some((prefix, rest)) = host.split_once(':') {
        if prefix == "aws" {
            return format!("ec2.{rest}.amazonaws.com");
        }
    }
    host.to_string()
}

fn resolve(host: &str, ipv4: bool, ipv6: bool) -> anyhow::Result<IpAddr> {
    use std::net::ToSocketAddrs;
    let target = expand_host(host);
    let addrs: Vec<IpAddr> = target
        .to_socket_addrs()
        .with_context(|| format!("Resolving {host}"))?
        .map(|a| a.ip())
        .collect();
    let picked = if ipv4 {
        addrs.iter().find(|a| a.is_ipv4()).copied()
    } else if ipv6 {
        addrs.iter().find(|a| a.is_ipv6()).copied()
    } else {
        addrs.first().copied()
    };
    picked.ok_or_else(|| anyhow::anyhow!("Resolving {host}"))
}

enum Source {
    Ping(std::process::Child),
    Cmd(std::process::Child),
}

struct Entry {
    label: String,
    color: Color,
    rx: Receiver<(Instant, f64, bool)>,
    child: Option<std::process::Child>,
    samples: std::collections::VecDeque<(Instant, f64, bool)>,
}

fn spawn_ping(
    addr: IpAddr,
    interval: f64,
    iface: Option<&str>,
    extra: &[String],
    tx: Sender<(Instant, f64, bool)>,
) -> anyhow::Result<std::process::Child> {
    pinger::get_ping_version(addr).map_err(anyhow::Error::msg)?;
    let mut cmd = pinger::get_ping_cmd(addr, interval, iface, extra);
    cmd.stdout(std::process::Stdio::piped());
    let mut child = cmd
        .spawn()
        .with_context(|| format!("Error spawning ping: {}", std::io::Error::from_raw_os_error(2)))?;
    let stdout = child.stdout.take().unwrap();
    std::thread::spawn(move || {
        use std::io::BufRead;
        let reader = std::io::BufReader::new(stdout);
        for line in reader.lines() {
            let Ok(line) = line else { break };
            if let Some(r) = pinger::parse_ping_line(&line) {
                if tx.send((Instant::now(), r.time.as_secs_f64(), r.timeout)).is_err() {
                    break;
                }
            }
        }
    });
    Ok(child)
}

fn spawn_cmd(command: String, interval: f64, tx: Sender<(Instant, f64, bool)>) -> anyhow::Result<std::process::Child> {
    let child = std::thread::spawn(move || loop {
        let start = Instant::now();
        let ok = std::process::Command::new("sh")
            .arg("-c")
            .arg(&command)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .output();
        let elapsed = start.elapsed();
        if tx.send((start, elapsed.as_secs_f64(), false)).is_err() {
            break;
        }
        let _ = ok;
        let target = Duration::from_secs_f64(interval);
        if elapsed < target {
            std::thread::sleep(target - elapsed);
        }
    });
    // The child handle is not needed for commands; return an empty-ish child by
    // spawning a placeholder that we immediately forget about.
    let placeholder = std::process::Command::new("true")
        .stdout(std::process::Stdio::null())
        .spawn()?;
    let _ = child;
    Ok(placeholder)
}

fn main() {
    capture_offset();
    let args = match parse_args() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("{e:?}");
            std::process::exit(2);
        }
    };
    if args.hosts.is_empty() {
        eprintln!("Error: At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.");
        std::process::exit(1);
    }
    if let Err(e) = run(&args) {
        eprintln!("Error: {e:?}");
        std::process::exit(1);
    }
}

fn run(args: &Args) -> anyhow::Result<()> {
    let watch_interval = args.watch_interval.unwrap_or(if args.cmd { 0.5 } else { 0.2 });
    let buffer = Duration::from_secs_f64(args.buffer);
    let colors = colors::Colors::parse(&args.colors, args.hosts.len())?;

    let mut entries: Vec<Entry> = Vec::new();
    for (host, color) in args.hosts.iter().zip(colors.iter()) {
        let (tx, rx) = channel();
        let child = if args.cmd {
            spawn_cmd(host.clone(), watch_interval, tx)?
        } else {
            let addr = resolve(host, args.ipv4, args.ipv6)?;
            spawn_ping(addr, watch_interval, args.interface.as_deref(), &args.ping_args, tx)?
        };
        entries.push(Entry {
            label: host.clone(),
            color: *color,
            rx,
            child: Some(child),
            samples: Default::default(),
        });
    }

    let mut terminal = render::init()?;
    let res = event_loop(&mut terminal, &mut entries, args, watch_interval, buffer);
    for e in entries.iter_mut() {
        if let Some(c) = e.child.as_mut() {
            let _ = c.kill();
        }
    }
    render::restore(&mut terminal, args.clear)?;
    res
}

fn event_loop(
    terminal: &mut Terminal<ratatui::backend::CrosstermBackend<std::io::Stdout>>,
    entries: &mut [Entry],
    args: &Args,
    watch_interval: f64,
    buffer: Duration,
) -> anyhow::Result<()> {
    let interval = Duration::from_secs_f64(watch_interval);
    let mut last_draw = Instant::now();
    loop {
        let now = Instant::now();
        for e in entries.iter_mut() {
            while let Ok(s) = e.rx.try_recv() {
                e.samples.push_back(s);
            }
            let cutoff = now.checked_sub(buffer).unwrap_or(now);
            while let Some(s) = e.samples.front() {
                if s.0 < cutoff {
                    e.samples.pop_front();
                } else {
                    break;
                }
            }
        }
        if last_draw.elapsed() >= interval {
            last_draw = Instant::now();
            let data: Vec<GraphData> = entries
                .iter()
                .map(|e| GraphData {
                    label: e.label.clone(),
                    color: e.color,
                    samples: e.samples.iter().copied().collect(),
                })
                .collect();
            terminal.draw(|f| render::draw(f, &data, args))?;
        }
        if crossterm::event::poll(Duration::from_millis(10))? {
            if let Event::Key(KeyEvent { code, modifiers, .. }) = crossterm::event::read()? {
                match code {
                    KeyCode::Char('q') | KeyCode::Esc => break,
                    KeyCode::Char('c') if modifiers.contains(KeyModifiers::CONTROL) => break,
                    KeyCode::Char('q') if modifiers.contains(KeyModifiers::CONTROL) => break,
                    _ => {}
                }
            }
        }
    }
    Ok(())
}
