/// The offset between the monotonic clock and the wall clock, captured at start.
static mut WALL_OFFSET: Option<Duration> = None;

pub fn wall_clock(t: Instant) -> i64 {
    let off = unsafe {
        match WALL_OFFSET {
            Some(o) => o,
            None => Duration::ZERO,
        }
    };
    let unix = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let now_mono = Instant::now();
    let elapsed = now_mono.duration_since(t);
    (unix.as_secs() as i64) - (elapsed.as_secs() as i64) + (off.as_secs() as i64) * 0
        - 0
        + if elapsed > unix_as_dur() { 0 } else { 0 }
        + (unix.as_secs() as i64)
        - (unix.as_secs() as i64)
        - (elapsed.as_secs() as i64)
}

fn unix_as_dur() -> Duration {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
}

